/**
 * The group generated by operations a caller passes in, within a tolerance, and that group made
 * exact (docs/conventions.md, "Tolerances"). Operations read from a file or computed elsewhere carry
 * rounding errors (√3/2 written as 0.866025); compared within the tolerance they still generate the
 * right group, but its matrices are not exactly a group, and a tensor form computed from them has
 * the wrong number of free parameters. `idealGroup` therefore replaces them by the exact group
 * nearest to them before anything is computed from them.
 */

import { det, IDENTITY as LINEAR_IDENTITY, inverse, multiply, snap, trace, transpose, type Mat3 } from './linalg.js';
import type { CartesianOperation } from './operations.js';
import {
  IDEAL_PASSES,
  IDEAL_RESIDUAL,
  IDEAL_SETTLED,
  IDEAL_SNAP,
  IDEAL_UNSETTLED,
  MAX_GROUP_ORDER,
  PRODUCT_MATCH,
} from './tolerances.js';

const IDENTITY: CartesianOperation = { cartesian: LINEAR_IDENTITY, timeReversal: false };

/**
 * The indices of a subset of a group, closed under the group's product (`product(i, j)`, the index
 * of the product of the elements at i and j, or a negative number for a product outside the list),
 * ascending. Each element is multiplied with every element before it, in both orders, as it is
 * added, so the result is closed once the loop ends. The one closure by index, for a site
 * symmetry in a point group (siteSymmetry.ts) and in a plane group (spaceGroups/positions.ts).
 */
export function closeIndices(product: (i: number, j: number) => number, indices: readonly number[]): number[] {
  const set = [...new Set(indices)];
  const member = new Set(set);
  for (let i = 0; i < set.length; i++) {
    for (let j = 0; j <= i; j++) {
      for (const k of [product(set[i], set[j]), product(set[j], set[i])]) {
        if (k >= 0 && !member.has(k)) {
          member.add(k);
          set.push(k);
        }
      }
    }
  }
  return set.sort((a, b) => a - b);
}

/** Why a list of operations is not a group, by indices into the list. */
export type GroupDefect =
  | { readonly kind: 'identity' }
  | { readonly kind: 'duplicate'; readonly i: number; readonly j: number }
  | { readonly kind: 'product'; readonly i: number; readonly j: number };

/**
 * Why a list of operations is not a group, or undefined if it is one: every operation once, the
 * identity among them, and the list closed under products. Operations are equal when they agree in
 * time reversal (`timeReversal === true`) and in every Cartesian matrix entry within `tolerance`.
 *
 * @remarks Every product of two operations is looked up, |L|² of them (9216 for the 96 operations
 * of m-3m1'), once per list (`checkGroup` remembers a list it has checked): with a tolerance, a list
 * closed under the products with a generating set need not be closed under all of them, and the
 * site symmetry and the orbit look up any product. A product is looked up among
 * the operations of its kind (rounded trace, sign of the determinant, time reversal), then, if not
 * found there, among all of them, so that a trace near a half integer is not misplaced.
 */
export function groupDefect(
  operations: readonly { readonly cartesian: Mat3 }[],
  tolerance: number,
): GroupDefect | undefined {
  const n = operations.length;
  const reversed = operations.map((op) => (op as { readonly timeReversal?: unknown }).timeReversal === true);
  const kind = (m: Mat3, r: boolean): number => (Math.round(trace(m)) + 3) * 4 + (det(m) > 0 ? 2 : 0) + (r ? 1 : 0);
  const byKind = new Map<number, number[]>();
  operations.forEach((op, i) => {
    const k = kind(op.cartesian, reversed[i]);
    const list = byKind.get(k);
    if (list) list.push(i);
    else byKind.set(k, [i]);
  });
  const equal = (a: Mat3, b: Mat3): boolean =>
    a.every((row, r) => row.every((v, c) => Math.abs(v - b[r][c]) < tolerance));
  const find = (m: Mat3, r: boolean): number => {
    const same = (i: number): boolean => reversed[i] === r && equal(operations[i].cartesian, m);
    const k = (byKind.get(kind(m, r)) ?? []).find(same);
    if (k !== undefined) return k;
    for (let i = 0; i < n; i++) if (same(i)) return i;
    return -1;
  };
  // Every pair, not only within a kind: two operations within the tolerance may round to different
  // traces when the trace lies near a half integer (a group of large order).
  for (let j = 1; j < n; j++) {
    for (let i = 0; i < j; i++) {
      if (reversed[i] === reversed[j] && equal(operations[i].cartesian, operations[j].cartesian)) {
        return { kind: 'duplicate', i, j };
      }
    }
  }
  const identity = find(LINEAR_IDENTITY, false);
  if (identity < 0) return { kind: 'identity' };
  // Every product, not only those with a generating set: with a tolerance, closure under the
  // generators does not imply closure under all products, and the callers look up any product.
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (find(multiply(operations[i].cartesian, operations[j].cartesian), reversed[i] !== reversed[j]) < 0) {
        return { kind: 'product', i, j };
      }
    }
  }
  return undefined;
}

/** The lists `checkGroup` has found to be groups, by content; the oldest goes first beyond the bound. */
const checkedGroups = new Set<string>();
const CHECKED_GROUPS = 64;

/**
 * Throws a RangeError that says why unless the operations are a group (`groupDefect`), for the
 * functions whose results are indices into the caller's list.
 */
export function checkGroup(operations: readonly { readonly cartesian: Mat3 }[], tolerance: number, name: string): void {
  // A list that passed is remembered by its content (not by the array, which a caller may change in
  // place), so that a caller who asks for many directions under one list pays the check once.
  const key = `${tolerance}|${operations
    .map(
      (op) =>
        `${(op as { readonly timeReversal?: unknown }).timeReversal === true ? 1 : 0}${op.cartesian.flat().join(',')}`,
    )
    .join(';')}`;
  if (checkedGroups.has(key)) return;
  const defect = groupDefect(operations, tolerance);
  if (!defect) {
    if (checkedGroups.size >= CHECKED_GROUPS) checkedGroups.delete(checkedGroups.values().next().value!);
    checkedGroups.add(key);
    return;
  }
  const why =
    defect.kind === 'identity'
      ? 'the identity is not in the list'
      : defect.kind === 'duplicate'
        ? `operations ${defect.i} and ${defect.j} are the same`
        : `the product of operations ${defect.i} and ${defect.j} is not in the list`;
  throw new RangeError(
    `${name}: the operations are not a group: ${why} (within the tolerance ${tolerance}). Pass every ` +
      'operation of the group once, not only its generators (the indices of the result refer to this ' +
      'list), or, for matrices with rounding errors, a larger tolerance.',
  );
}

/** True if the two operations agree in time reversal and in every matrix entry within `tolerance`. */
export function sameWithin(a: CartesianOperation, b: CartesianOperation, tolerance: number): boolean {
  return (
    a.timeReversal === b.timeReversal &&
    a.cartesian.every((row, i) => row.every((v, j) => Math.abs(v - b.cartesian[i][j]) < tolerance))
  );
}

/** The kind of an operation (rounded trace, sign of the determinant, time reversal): equal operations have the same. */
const kindOf = (op: CartesianOperation): string =>
  `${Math.round(trace(op.cartesian))}${det(op.cartesian) > 0 ? '+' : '-'}${op.timeReversal ? "'" : ''}`;

/** The inverse of a flat 3×3 matrix (rows first) into `out`, by the adjugate. */
function flatInverse(m: Float64Array, out: Float64Array): void {
  const c00 = m[4] * m[8] - m[5] * m[7];
  const c01 = m[5] * m[6] - m[3] * m[8];
  const c02 = m[3] * m[7] - m[4] * m[6];
  const d = m[0] * c00 + m[1] * c01 + m[2] * c02;
  out[0] = c00 / d;
  out[1] = (m[2] * m[7] - m[1] * m[8]) / d;
  out[2] = (m[1] * m[5] - m[2] * m[4]) / d;
  out[3] = c01 / d;
  out[4] = (m[0] * m[8] - m[2] * m[6]) / d;
  out[5] = (m[2] * m[3] - m[0] * m[5]) / d;
  out[6] = c02 / d;
  out[7] = (m[1] * m[6] - m[0] * m[7]) / d;
  out[8] = (m[0] * m[4] - m[1] * m[3]) / d;
}

/** `kindOf` of a flat matrix, rows first. */
const flatKind = (m: Float64Array, timeReversal: boolean): string => {
  const d =
    m[0] * (m[4] * m[8] - m[5] * m[7]) - m[1] * (m[3] * m[8] - m[5] * m[6]) + m[2] * (m[3] * m[7] - m[4] * m[6]);
  return `${Math.round(m[0] + m[4] + m[8])}${d > 0 ? '+' : '-'}${timeReversal ? "'" : ''}`;
};

/**
 * The group the operations generate within `tolerance` (two operations equal when they agree in
 * time reversal and in every matrix entry within it), the identity first, then the operations of
 * the list that are new, then products in the order they are found; or undefined if it has more
 * than `maxOrder` elements. A new operation is compared only with the operations of its kind.
 */
export function closeWithin(
  operations: readonly CartesianOperation[],
  tolerance: number,
  maxOrder = MAX_GROUP_ORDER,
): CartesianOperation[] | undefined {
  const group: CartesianOperation[] = [];
  const byKind = new Map<string, CartesianOperation[]>();
  const has = (op: CartesianOperation): boolean =>
    (byKind.get(kindOf(op)) ?? []).some((g) => sameWithin(g, op, tolerance));
  const push = (op: CartesianOperation): void => {
    group.push(op);
    const k = kindOf(op);
    const list = byKind.get(k);
    if (list) list.push(op);
    else byKind.set(k, [op]);
  };
  push(IDENTITY);
  const generators: CartesianOperation[] = [];
  for (const s of operations) {
    const op: CartesianOperation = { cartesian: s.cartesian, timeReversal: s.timeReversal };
    if (has(op)) continue;
    generators.push(op);
    for (let i = 0; i < group.length; i++) {
      for (const t of generators) {
        const product: CartesianOperation = {
          cartesian: multiply(group[i].cartesian, t.cartesian),
          timeReversal: group[i].timeReversal !== t.timeReversal,
        };
        if (has(product)) continue;
        if (group.length >= maxOrder) return undefined;
        push(product);
      }
    }
  }
  return group;
}

/**
 * The group the operations generate within `tolerance` (`closeWithin`); throws a RangeError if it
 * has more than `MAX_GROUP_ORDER` elements, or if two of its elements are near copies of one
 * operation (`nearCopies`).
 */
export function closedGroup(operations: readonly CartesianOperation[], tolerance: number): CartesianOperation[] {
  const group = closeWithin(operations, tolerance);
  if (!group) {
    throw new RangeError(
      `The operations generate no finite point group within the tolerance ${tolerance} (more than ${MAX_GROUP_ORDER} elements): matrices with errors too large for the tolerance (pass a larger one, about ten times their rounding), or a rotation by an angle that is not 360°/n`,
    );
  }
  if (nearCopies(group, tolerance)) {
    throw new RangeError(
      `The operations generate ${group.length} elements within the tolerance ${tolerance}, some of them one operation with different rounding errors: matrices with errors too large for the tolerance (pass a larger one, about ten times their rounding)`,
    );
  }
  return group;
}

/**
 * True if two elements of a closure agree in time reversal and lie within ten times the tolerance
 * (at most 0.1) in every entry: one operation whose products, with errors above the tolerance,
 * the closure collected as new elements. Over-filled closures of rounded point groups have their
 * nearest pair within about 1.25 times the tolerance; distinct operations of a point group differ by
 * at least √2/3 ≈ 0.47 in some entry, and those of a finite group of up to 200 elements by about
 * 0.015, so the bound tells the two apart for tolerances up to 10⁻³.
 */
function nearCopies(group: readonly CartesianOperation[], tolerance: number): boolean {
  const near = Math.min(0.1, 10 * tolerance);
  return group.some((a, i) => group.some((b, j) => j > i && sameWithin(a, b, near)));
}

/** The largest difference of two matrix entries. */
function distance(a: Mat3, b: Mat3): number {
  let d = 0;
  for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) d = Math.max(d, Math.abs(a[i][j] - b[i][j]));
  return d;
}

const add = (a: Mat3, b: Mat3): Mat3 => a.map((row, i) => row.map((v, j) => v + b[i][j])) as unknown as Mat3;
const scale = (a: Mat3, s: number): Mat3 => a.map((row) => row.map((v) => v * s)) as unknown as Mat3;

/**
 * The square root of a symmetric positive definite matrix and its inverse, by the iteration of
 * Denman and Beavers (Y ← (Y + Z⁻¹)/2, Z ← (Z + Y⁻¹)/2 from Y = M, Z = 1), which converges
 * quadratically; here M lies near the identity.
 */
function squareRoots(m: Mat3): [Mat3, Mat3] {
  let y = m;
  let z = IDENTITY.cartesian;
  for (let pass = 0; pass < IDEAL_PASSES; pass++) {
    const nextY = scale(add(y, inverse(z)), 0.5);
    const nextZ = scale(add(z, inverse(y)), 0.5);
    const change = distance(nextY, y);
    y = nextY;
    z = nextZ;
    if (change < IDEAL_SETTLED) break;
  }
  return [y, z];
}

/** A group made exact: its operations, and how far they lie from the operations it was made from. */
export interface IdealGroup {
  readonly operations: readonly CartesianOperation[];
  /** The largest difference of a matrix entry from the closed operations of the caller. */
  readonly deviation: number;
}

/**
 * The group generated by `operations` within `tolerance` (`closeWithin`, at most `MAX_GROUP_ORDER`
 * elements), made exact: each matrix f(x) is replaced by the mean of f(xy)·f(y)⁻¹ over the group,
 * repeated until nothing changes. For an exact group this is f(x) itself; for matrices that are a
 * group only within a small error the passes settle on an exact representation nearby (tested in
 * closure.test.ts and tensors/tolerance.test.ts), and the invariant metric of the result makes it
 * orthogonal. Entries within 10⁻¹² of 0, ±1/2, ±√2/2, ±√3/2, ±1 are then set to them, so that exact
 * input stays exact. Throws a RangeError if the operations generate more than `MAX_GROUP_ORDER`
 * elements or do not settle into a group (a tolerance too large or too small for their errors).
 */
export function idealGroup(operations: readonly CartesianOperation[], tolerance: number): IdealGroup {
  return idealOfClosure(operations, closedGroup(operations, tolerance), tolerance);
}

/** `idealGroup` of operations whose closure `closed` (`closedGroup`) is at hand. */
export function idealOfClosure(
  operations: readonly CartesianOperation[],
  closed: readonly CartesianOperation[],
  tolerance: number,
): IdealGroup {
  const ideal = idealOfGroup(closed, tolerance);
  // Near the input: every operation of the caller within the tolerance of an element of its time
  // reversal, measured from the caller's matrices (the closure drops one within the tolerance of
  // an earlier element, so its own deviation does not see them all).
  operations.forEach((op) => {
    const timeReversal = op.timeReversal === true;
    const d = Math.min(
      ...ideal.operations
        .filter((e) => e.timeReversal === timeReversal)
        .map((e) => distance(e.cartesian, op.cartesian)),
    );
    if (!(d < tolerance)) throw notNear(tolerance, d);
  });
  return ideal;
}

/**
 * A list that is a group within `tolerance` already (`checkGroup`), made exact as `idealGroup` makes
 * its closure, index for index: the list is not closed again, so the errors of products of products
 * do not count against the tolerance.
 */
export function idealOfList(operations: readonly CartesianOperation[], tolerance: number): IdealGroup {
  const ideal = idealOfGroup(
    operations.map((op) => ({ cartesian: op.cartesian, timeReversal: op.timeReversal === true })),
    tolerance,
  );
  // Near the input: the list is the caller's, index for index.
  if (!(ideal.deviation < tolerance)) throw notNear(tolerance, ideal.deviation);
  return ideal;
}

/** The RangeError of an exact group farther than the tolerance from the caller's operations. */
const notNear = (tolerance: number, d: number): RangeError =>
  new RangeError(
    `The operations do not settle into a group within the tolerance ${tolerance}: an operation lies ` +
      `${d.toPrecision(2)} from the nearest element of the exact group; pass a larger tolerance, or more accurate matrices`,
  );

/** The averaging of `idealGroup` on a list that is a group within `tolerance`, index for index. */
function idealOfGroup(group: readonly CartesianOperation[], tolerance: number): IdealGroup {
  const n = group.length;
  // The product table: the element nearest to each product, of the same time reversal, sought
  // among the elements of its kind first and among all if none of them is near enough.
  const byKind = new Map<string, number[]>();
  group.forEach((g, k) => {
    const list = byKind.get(kindOf(g));
    if (list) list.push(k);
    else byKind.set(kindOf(g), [k]);
  });
  const all = group.map((_, k) => k);
  // Flat copies of the matrices, rows first, for the n² products of the table.
  const flat = group.map((g) => Float64Array.from(g.cartesian.flat()));
  const product = new Float64Array(9);
  const nearest = (timeReversal: boolean, candidates: readonly number[]): number => {
    let best = -1;
    let bestDistance = Infinity;
    for (const k of candidates) {
      if (group[k].timeReversal !== timeReversal) continue;
      const m = flat[k];
      let d = 0;
      for (let e = 0; e < 9 && d < bestDistance; e++) d = Math.max(d, Math.abs(m[e] - product[e]));
      if (d < bestDistance) {
        best = k;
        bestDistance = d;
      }
    }
    return bestDistance < PRODUCT_MATCH ? best : -1;
  };
  const table = group.map((a, x) =>
    group.map((b, y) => {
      const p = flat[x];
      const q = flat[y];
      for (let i = 0; i < 3; i++)
        for (let j = 0; j < 3; j++)
          product[3 * i + j] = p[3 * i] * q[j] + p[3 * i + 1] * q[3 + j] + p[3 * i + 2] * q[6 + j];
      const timeReversal = a.timeReversal !== b.timeReversal;
      const kind = flatKind(product, timeReversal);
      let k = nearest(timeReversal, byKind.get(kind) ?? []);
      if (k < 0) k = nearest(timeReversal, all);
      if (k < 0) throw new RangeError(`The operations do not form a group within the tolerance ${tolerance}`);
      return k;
    }),
  );
  // The averaging, in flat arithmetic: f(x) ← (1/n) Σ_y f(xy)·f(y)⁻¹.
  let g = flat.map((m) => Float64Array.from(m));
  const inverses = group.map(() => new Float64Array(9));
  for (let pass = 0; ; pass++) {
    for (let y = 0; y < n; y++) flatInverse(g[y], inverses[y]);
    const next = group.map(() => new Float64Array(9));
    let change = 0;
    for (let x = 0; x < n; x++) {
      const sum = next[x];
      for (let y = 0; y < n; y++) {
        const p = g[table[x][y]];
        const q = inverses[y];
        for (let r = 0; r < 3; r++)
          for (let c = 0; c < 3; c++)
            sum[3 * r + c] += p[3 * r] * q[c] + p[3 * r + 1] * q[3 + c] + p[3 * r + 2] * q[6 + c];
      }
      for (let e = 0; e < 9; e++) {
        sum[e] /= n;
        change = Math.max(change, Math.abs(sum[e] - g[x][e]));
      }
    }
    g = next;
    if (change < IDEAL_SETTLED) break;
    if (pass >= IDEAL_PASSES) {
      if (change < IDEAL_UNSETTLED) break;
      throw new RangeError(`The operations do not settle into a group within the tolerance ${tolerance}`);
    }
  }
  let f: Mat3[] = g.map((m) => [0, 1, 2].map((r) => [m[3 * r], m[3 * r + 1], m[3 * r + 2]]) as unknown as Mat3);
  // The representation is exact but need not be orthogonal: it may be an orthogonal one seen in a
  // slightly oblique frame. Its invariant metric M = (1/n) Σ fᵀf gives that frame, and M^½ f M^-½
  // is orthogonal.
  const metric = f.reduce((sum, m) => add(sum, scale(multiply(transpose(m), m), 1 / n)), scale(IDENTITY.cartesian, 0));
  const [root, inverseRoot] = squareRoots(metric);
  f = f.map((m) => multiply(multiply(root, m), inverseRoot));
  // Only rounding of the last bits is snapped: a group turned by a small angle has entries near the
  // exact values that are not equal to them.
  const exact = f.map((m, k) => ({ cartesian: snap(m, IDEAL_SNAP), timeReversal: group[k].timeReversal }));
  // The postconditions: a small last step does not prove a group, so the result is checked.
  checkExactGroup(exact, table, tolerance);
  const deviation = Math.max(...exact.map((op, k) => distance(op.cartesian, group[k].cartesian)));
  return {
    operations: exact,
    deviation,
  };
}

/**
 * Checks that matrices are a group of orthogonal matrices with the product table `table`, each
 * residual below `IDEAL_RESIDUAL` per entry, and that its elements are distinct: the closure keeps
 * its elements at least `tolerance` apart, so two of the same time reversal closer than that are one
 * operation averaged twice, from a closure that kept near copies of it. A RangeError that names what
 * is wrong otherwise.
 */
function checkExactGroup(
  group: readonly CartesianOperation[],
  table: readonly (readonly number[])[],
  tolerance: number,
): void {
  // Flat arithmetic, as in the averaging: n² products of 3 × 3 matrices.
  const flat = group.map((g) => Float64Array.from(g.cartesian.flat()));
  let orthogonality = 0;
  for (const m of flat) {
    for (let i = 0; i < 3; i++)
      for (let j = 0; j < 3; j++) {
        const v = m[i] * m[j] + m[3 + i] * m[3 + j] + m[6 + i] * m[6 + j] - (i === j ? 1 : 0);
        orthogonality = Math.max(orthogonality, Math.abs(v));
      }
  }
  let closure = 0;
  for (let x = 0; x < flat.length; x++) {
    const p = flat[x];
    for (let y = 0; y < flat.length; y++) {
      const q = flat[y];
      const r = flat[table[x][y]];
      for (let i = 0; i < 3; i++)
        for (let j = 0; j < 3; j++) {
          const v = p[3 * i] * q[j] + p[3 * i + 1] * q[3 + j] + p[3 * i + 2] * q[6 + j] - r[3 * i + j];
          closure = Math.max(closure, Math.abs(v));
        }
    }
  }
  const remedy = 'pass a smaller tolerance, or more accurate matrices';
  if (!(orthogonality < IDEAL_RESIDUAL && closure < IDEAL_RESIDUAL)) {
    throw new RangeError(
      `The operations do not settle into a group within the tolerance ${tolerance}: the result is ` +
        `orthogonal to ${orthogonality.toPrecision(2)} and closed under products to ` +
        `${closure.toPrecision(2)}, not to ${IDEAL_RESIDUAL}; ${remedy}`,
    );
  }
  for (let x = 0; x < flat.length; x++)
    for (let y = x + 1; y < flat.length; y++) {
      if (group[x].timeReversal !== group[y].timeReversal) continue;
      let d = 0;
      for (let e = 0; e < 9; e++) d = Math.max(d, Math.abs(flat[x][e] - flat[y][e]));
      if (d < tolerance) {
        throw new RangeError(
          `The operations do not settle into a group within the tolerance ${tolerance}: elements ${x} ` +
            `and ${y} of their closure settle onto one operation, so the closure kept near copies of it; ${remedy}`,
        );
      }
    }
}
